common="""const project=await eda.dmt_Project.getCurrentProjectInfo();if(project.uuid!==PROJECT)throw Error('Wrong final copy');async function find(ref){const cs=(await eda.sch_PrimitiveComponent.getAll()).filter(c=>c.getState_ComponentType()==='part'&&c.getState_Designator()===ref);if(cs.length!==1)throw Error('Wrong ref '+ref);return cs[0];}async function create(q,x,y){const c=await eda.sch_PrimitiveComponent.create(q.association,x,y,q.sub,0,false,true,true);if(!c)throw Error('create '+q.ref);const m=await eda.sch_PrimitiveComponent.modify(c.getState_PrimitiveId(),{designator:q.ref,name:q.value,otherProperty:{...c.getState_OtherProperty(),Value:q.value,'Add into BOM':'yes',DNP:'no',Manufacturer:q.manufacturer||'YAGEO',MPN:q.MPN||q.name,'Review Status':'C final candidate / noPCBbenchrelease','Circuit Role':q.role}});if(!m)throw Error('modify '+q.ref);const pins=await eda.sch_PrimitiveComponent.getAllPinsByPrimitiveId(m.getState_PrimitiveId());if(pins.length!==Object.keys(q.nets).length||pins.some(z=>!(String(z.getState_PinNumber())in q.nets)))throw Error('Pinset '+q.ref);const result=[];for(const z of pins){const num=String(z.getState_PinNumber()),name=z.getState_PinName();if(q.ref==='D_LDO_REV'&&!((num==='1'&&/K|Cathode/i.test(name))||(num==='2'&&/A|Anode/i.test(name))))throw Error('Diode actualpolarity');await z.setState_NoConnected(false).done();const delta={0:[120,0],180:[-120,0],90:[0,120],270:[0,-120]}[z.getState_Rotation()];if(!delta)throw Error('Pinrotation');const port=await eda.sch_PrimitiveComponent.createNetPort('BI',q.nets[num],z.getState_X()+delta[0],z.getState_Y()+delta[1],z.getState_Rotation(),false);if(!port)throw Error('port');const a=await eda.sch_PrimitiveComponent.getAllPinsByPrimitiveId(port.getState_PrimitiveId());const w=await eda.sch_PrimitiveWire.create([[z.getState_X(),z.getState_Y(),a[0].getState_X(),a[0].getState_Y()]],q.nets[num]);if(!w)throw Error('wire');result.push({num,name,net:q.nets[num]});}return{ref:q.ref,pins:result};}\n""".replace('PROJECT',json.dumps(base['project']))
script0=common+"await eda.dmt_EditorControl.openDocument('595d5f2f11dee03d');const added=await create(DIODE,2070,120);const saved=await eda.sch_Document.save();if(saved!==true)throw Error('save');return{added,saved};".replace('DIODE',json.dumps(parts[-1],ensure_ascii=False))
