script1=common+"await eda.dmt_EditorControl.openDocument('802bf258e0d38cab');const out=[];for(const ref of ['D_FFC_ROW','D_FFC_COL']){const c=await find(ref);const m=await eda.sch_PrimitiveComponent.modify(c.getState_PrimitiveId(),{otherProperty:{...c.getState_OtherProperty(),Manufacturer:'Texas Instruments',MPN:'TPD4E05U06DQAR','Manufacturer Part':'TPD4E05U06DQAR','Circuit Role':'J2 passive-only ESD, notcontinuousDCfault','Review Status':'C final candidate / noPCBbenchrelease'}});if(!m)throw Error('TPDmodify');out.push({ref,props:m.getState_OtherProperty()});}const saved=await eda.sch_Document.save();if(saved!==true)throw Error('save');return{out,saved};"
